const fs = require('fs');

function solve() {
    const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (data.length < 2) return;
    const N = parseInt(data[0], 10);
    const P_str = data[1];

    // Parse P string to integer representing ten-thousandths (0 to 10000)
    let P_int = 0;
    if (P_str.includes('.')) {
        const parts = P_str.split('.');
        const intPart = parts[0];
        let fracPart = parts[1] || '';
        fracPart = (fracPart + '0000').substring(0, 4);
        P_int = parseInt(intPart) * 10000 + parseInt(fracPart);
    } else {
        P_int = parseInt(P_str) * 10000;
    }

    const TOTAL = 10000;

    // If P is 0, no maps need to be studied
    if (P_int === 0) {
        console.log(0);
        return;
    }

    // Helper to compute probability of playing a studied map given k studied maps
    // Returns numerator / (N * (N-1) * (N-2)) basically, but we compare cross-multiplied
    // P_game = (3k * N^2 + k * (-9N + 8) - 2k^3) / (N * (N-1) * (N-2))
    // Let Num(k) = 3k*N^2 + k*(-9N+8) - 2k^3
    // Let Den = N*(N-1)*(N-2)
    // We want Num(k) / Den >= P_int / TOTAL
    // i.e., Num(k) * TOTAL >= P_int * Den
    const Den = N * (N - 1) * (N - 2);
    const target = P_int * Den;

    const getNum = (k) => {
        // Use integers, values fit in 64-bit (JS Number safe up to 2^53 ~ 9e15)
        // Max N=1000, k=1000.
        // Terms: 3k N^2 ~ 3e9, k*9N ~ 9e6, 2k^3 ~ 2e9. Sum ~ 5e9.
        // Num * TOTAL ~ 5e13. Safe.
        return 3 * k * N * N + k * (-9 * N + 8) - 2 * k * k * k;
    };

    // Binary search for minimum k in [1, N-1]
    let low = 1;
    let high = N - 1;
    let ans = N - 1;

    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        const num = getNum(mid);
        if (num * TOTAL >= target) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    console.log(ans);
}

solve();
